   858	 * When a task is deleted, the parentReportAction is updated to have a isDeletedParentAction deleted flag
   859	 * This is because when you delete a task, we still allow you to chat on the report itself
   860	 * There's another situation where you don't have access to the parentReportAction (because it was created in a chat you don't have access to)
   861	 * In this case, we have added the key to the report itself
   862	 */
   863	function isCanceledTaskReport(report: OnyxInputOrEntry<Report>, parentReportAction: OnyxInputOrEntry<ReportAction> = null): boolean {
   864	    if (!isEmptyObject(parentReportAction) && (ReportActionsUtils.getReportActionMessage(parentReportAction)?.isDeletedParentAction ?? false)) {
   865	        return true;
   866	    }
   867	
   868	    if (!isEmptyObject(report) && report?.isDeletedParentAction) {
   869	        return true;
   870	    }
   871	
   872	    return false;
   873	}
   874	
   875	/**
   876	 * Checks if a report is an open task report.
   877	 *
   878	 * @param parentReportAction - The parent report action of the report (Used to check if the task has been canceled)
   879	 */
   880	function isOpenTaskReport(report: OnyxInputOrEntry<Report>, parentReportAction: OnyxInputOrEntry<ReportAction> = null): boolean {
   881	    return (
   882	        isTaskReport(report) && !isCanceledTaskReport(report, parentReportAction) && report?.stateNum === CONST.REPORT.STATE_NUM.OPEN && report?.statusNum === CONST.REPORT.STATUS_NUM.OPEN
   883	    );
   884	}
