   889	function isCompletedTaskReport(report: OnyxEntry<Report>): boolean {
   890	    return isTaskReport(report) && report?.stateNum === CONST.REPORT.STATE_NUM.APPROVED && report?.statusNum === CONST.REPORT.STATUS_NUM.APPROVED;
   891	}
