   925	/**
   926	 * Checks if the supplied report has a member with the array passed in params.
   927	 */
   928	function hasParticipantInArray(report: OnyxEntry<Report>, memberAccountIDs: number[]) {
   929	    if (!report?.participants) {
   930	        return false;
   931	    }
   932	
   933	    const memberAccountIDsSet = new Set(memberAccountIDs);
   934	
   935	    for (const accountID in report.participants) {
   936	        if (memberAccountIDsSet.has(Number(accountID))) {
   937	            return true;
   938	        }
   939	    }
   940	
   941	    return false;
   942	}
