   944	/**
   945	 * Whether the Money Request report is settled
   946	 */
   947	function isSettled(reportID: string | undefined): boolean {
   948	    const allReports = ReportConnection.getAllReports();
   949	    if (!allReports || !reportID) {
   950	        return false;
   951	    }
   952	    const report = allReports[`${ONYXKEYS.COLLECTION.REPORT}${reportID}`] ?? null;
   953	    if (isEmptyObject(report) || report.isWaitingOnBankAccount) {
   954	        return false;
   955	    }
   956	
   957	    // In case the payment is scheduled and we are waiting for the payee to set up their wallet,
   958	    // consider the report as paid as well.
   959	    if (report.isWaitingOnBankAccount && report.statusNum === CONST.REPORT.STATUS_NUM.APPROVED) {
   960	        return true;
   961	    }
   962	
   963	    return report?.statusNum === CONST.REPORT.STATUS_NUM.REIMBURSED;
   964	}
